using UnityEngine;

// This class is now a pure calculator. It only determines the aim position and direction.
public class PlayerAiming
{
    private readonly Camera _cam;
    private readonly Transform _transform;

    public Vector3 AimDirection { get; private set; }
    public Vector3 AimPosition { get; private set; }

    public PlayerAiming(Camera cam, Transform transform)
    {
        _cam = cam;
        _transform = transform;
    }

    public void Tick()
    {
        Plane groundPlane = new Plane(Vector3.up, _transform.position);
        Ray ray = _cam.ScreenPointToRay(Input.mousePosition);

        if (groundPlane.Raycast(ray, out float enter))
        {
            AimPosition = ray.GetPoint(enter);
            AimDirection = (AimPosition - _transform.position).normalized;
        }
    }
}

using UnityEngine;

public class PlayerMovement
{
    // --- Settings ---
    private readonly float _moveSpeed;
    private readonly float _accelerationTime;

    // --- Dash Settings ---
    private readonly float _dashSpeed = 30f;
    private readonly float _dashDuration = 0.1f;
    private readonly float _dashCooldown = 1f;

    // --- References ---
    private readonly CharacterController _controller;
    private readonly Transform _transform;
    private readonly Transform _cameraTransform;

    // --- State ---
    private Vector3 _currentMoveVelocity;
    private Vector3 _velocityDamper;
    private float _dashCooldownTimer;
    private float _dashTimer;
    private bool _isDashing;
    private Vector3 _dashDirection;

    // --- Public State ---
    public bool JustDashed { get; private set; }
    public float DashCooldownTimer => _dashCooldownTimer;

    public PlayerMovement(CharacterController controller, Transform cameraTransform, float moveSpeed, float accelerationTime)
    {
        _controller = controller;
        _transform = controller.transform;
        _cameraTransform = cameraTransform;
        _moveSpeed = moveSpeed;
        _accelerationTime = accelerationTime;
    }

    public void Tick()
    {
        JustDashed = false; 
        Vector3 inputDirection = new Vector3(Input.GetAxisRaw("Horizontal"), 0f, Input.GetAxisRaw("Vertical"));
        HandleDashState(inputDirection);

        if (_isDashing)
        {
            _controller.Move(_dashDirection * _dashSpeed * Time.deltaTime);
            return;
        }

        HandleMovement(inputDirection);
    }

    private void HandleMovement(Vector3 inputDirection)
    {
        Vector3 targetVelocity;
        if (inputDirection.magnitude >= 0.1f)
        {
            Vector3 camForward = _cameraTransform.forward;
            Vector3 camRight = _cameraTransform.right;
            camForward.y = 0;
            camRight.y = 0;
            camForward.Normalize();
            camRight.Normalize();

            Vector3 targetDirection = (camForward * inputDirection.z + camRight * inputDirection.x).normalized;
            targetVelocity = targetDirection * _moveSpeed;
        }
        else
        {
            targetVelocity = Vector3.zero;
        }

        _currentMoveVelocity = Vector3.SmoothDamp(_currentMoveVelocity, targetVelocity, ref _velocityDamper, _accelerationTime);
        _controller.Move(_currentMoveVelocity * Time.deltaTime);
    }

    private void HandleDashState(Vector3 inputDirection)
    {
        if (_dashCooldownTimer > 0) _dashCooldownTimer -= Time.deltaTime;
        if (_dashTimer > 0)
        {
            _dashTimer -= Time.deltaTime;
            if (_dashTimer <= 0) _isDashing = false;
        }

        if (Input.GetKeyDown(KeyCode.Space) && _dashCooldownTimer <= 0)
        {
            StartDash(inputDirection);
        }
    }

    private void StartDash(Vector3 inputDirection)
    {
        JustDashed = true; 
        _isDashing = true;
        _dashCooldownTimer = _dashCooldown;
        _dashTimer = _dashDuration;

        if (inputDirection.magnitude >= 0.1f)
        {
            Vector3 camForward = _cameraTransform.forward;
            Vector3 camRight = _cameraTransform.right;
            camForward.y = 0;
            camRight.y = 0;
            camForward.Normalize();
            camRight.Normalize();
            _dashDirection = (camForward * inputDirection.z + camRight * inputDirection.x).normalized;
        }
        else
        {
            _dashDirection = _transform.forward;
        }
    }
}

using UnityEngine;
using Unity.Cinemachine;
using TMPro;

[RequireComponent(typeof(CharacterController))]
public class Player : MonoBehaviour
{
    // ... (wszystkie pola pozostają bez zmian)
    [Header("Dependencies")]
    [SerializeField] private GameObject _bulletPrefab;
    [SerializeField] private Transform _firePoint;
    [SerializeField] private Animator _animator;
    [SerializeField] private TextMeshProUGUI _dashCooldownText;

    [Header("Movement Settings")]
    [SerializeField] private float moveSpeed = 7f;
    [SerializeField] private float accelerationTime = 0.1f;

    [Header("Aiming IK Settings")]
    [Range(0, 1)]
    [SerializeField] private float _aimBodyWeight = 0.6f;
    [Range(0, 1)]
    [SerializeField] private float _aimHeadWeight = 0.9f;
    [Tooltip("The angle at which the whole body will start to turn.")]
    [SerializeField] private float _maxAimAngle = 80f;

    [Header("Impulse Sources")]
    [SerializeField] private CinemachineImpulseSource _dashImpulseSource;
    [SerializeField] private CinemachineImpulseSource _gunshotImpulseSource;

    private PlayerMovement _movement;
    private PlayerAiming _aiming;
    private PlayerShooting _shooting;
    private CharacterController _controller;
    private Quaternion _lastRotation;
    private float _turnSpeed;

    private readonly int _moveXHash = Animator.StringToHash("MoveX");
    private readonly int _moveYHash = Animator.StringToHash("MoveY");
    private readonly int _speedHash = Animator.StringToHash("Speed");
    private readonly int _turnSpeedHash = Animator.StringToHash("TurnSpeed");

    void Awake()
    {
        _controller = GetComponent<CharacterController>();
        var mainCamera = Camera.main;
        _aiming = new PlayerAiming(mainCamera, transform);
        _movement = new PlayerMovement(_controller, mainCamera.transform, moveSpeed, accelerationTime);
        _shooting = new PlayerShooting(transform, _firePoint, _bulletPrefab);
        if (_dashCooldownText != null) _dashCooldownText.gameObject.SetActive(false);
        _lastRotation = transform.rotation;
    }

    void Update()
    {
        // Update is now only for calculating AIM and basic MOVEMENT logic.
        _aiming.Tick();
        _movement.Tick();
        _shooting.Tick(_aiming.AimDirection);

        // We also send the calculated values to the animator here.
        // The values themselves are calculated in LateUpdate from the previous frame.
        UpdateAnimator();
        UpdateDashCooldownUI();

        // Handle events
        if (_movement.JustDashed && _dashImpulseSource != null) _dashImpulseSource.GenerateImpulse();
        if (Input.GetMouseButtonDown(0) && _gunshotImpulseSource != null) _gunshotImpulseSource.GenerateImpulse();
    }

    void LateUpdate()
    {
        // 1. APPLY ROTATION: The character's body is rotated first.
        float angle = Vector3.SignedAngle(transform.forward, _aiming.AimDirection, Vector3.up);
        if (Mathf.Abs(angle) > _maxAimAngle)
        {
            Quaternion targetRotation = Quaternion.LookRotation(_aiming.AimDirection);
            transform.rotation = Quaternion.Slerp(transform.rotation, targetRotation, Time.deltaTime * 15f);
        }

        // 2. MEASURE ROTATION: Immediately after rotating, we measure the speed of that rotation.
        // This ensures the data is perfectly synchronized with the visual change.
        CalculateTurnSpeed();
    }

    private void OnAnimatorIK(int layerIndex)
    {
        if (_animator == null) return;
        _animator.SetLookAtWeight(1f, _aimBodyWeight, _aimHeadWeight, 1f, 0.5f);
        if (_animator.GetBoneTransform(HumanBodyBones.Head) == null) return;
        Vector3 headPosition = _animator.GetBoneTransform(HumanBodyBones.Head).position;
        Vector3 lookAtTarget = headPosition + (_aiming.AimDirection * 100f);
        _animator.SetLookAtPosition(lookAtTarget);
    }

    private void CalculateTurnSpeed()
    {
        Quaternion currentRotation = transform.rotation;
        Quaternion deltaRotation = currentRotation * Quaternion.Inverse(_lastRotation);
        deltaRotation.ToAngleAxis(out float angle, out Vector3 axis);
        if (float.IsNaN(axis.x)) return;

        float turnDirection = Mathf.Sign(axis.y);
        float turnAnglePerSecond = (angle * turnDirection) / Time.deltaTime;
        float normalizedTurnSpeed = Mathf.Clamp(turnAnglePerSecond / 360f, -1f, 1f);

        // Increased Lerp factor for faster animation response
        _turnSpeed = Mathf.Lerp(_turnSpeed, normalizedTurnSpeed, Time.deltaTime * 20f); 

        _lastRotation = currentRotation;
    }

    private void UpdateAnimator()
    {
        if (_animator == null) return;
        Vector3 horizontalVelocity = new Vector3(_controller.velocity.x, 0, _controller.velocity.z);
        float currentSpeed = horizontalVelocity.magnitude;
        Vector3 localVelocity = transform.InverseTransformDirection(horizontalVelocity);
        float moveY = localVelocity.z / moveSpeed;
        float moveX = localVelocity.x / moveSpeed;
        _animator.SetFloat(_speedHash, currentSpeed);
        _animator.SetFloat(_turnSpeedHash, _turnSpeed);
        _animator.SetFloat(_moveXHash, moveX);
        _animator.SetFloat(_moveYHash, moveY);
    }

    private void UpdateDashCooldownUI()
    {
        if (_dashCooldownText == null) return;
        float cooldown = _movement.DashCooldownTimer;
        if (cooldown > 0)
        {
            _dashCooldownText.gameObject.SetActive(true);
            _dashCooldownText.text = cooldown.ToString("F1");
        }
        else
        {
            _dashCooldownText.gameObject.SetActive(false);
        }
    }
}

